// src/utils/jwt.ts
import jwt from "jsonwebtoken";
var createToken = (payload, secret, expiresIn) => {
  const token = jwt.sign(payload, secret, {
    expiresIn
  });
  return token;
};
var verifyToken = (token, secret) => {
  try {
    const decoded = jwt.verify(token, secret);
    return {
      success: true,
      data: decoded
    };
  } catch (error) {
    return {
      success: false,
      error: error.message
    };
  }
};
var jwtUtils = {
  createToken,
  verifyToken
};

// src/middleware/auth.Middleware.ts
var auth = (...requiredRoles) => {
  return catchAsync(async (req, res, next) => {
    const bearerToken = req.headers.authorization?.startsWith("Bearer ") ? req.headers.authorization.split(" ")[1] : req.headers.authorization;
    const token = req.cookies?.accessToken || bearerToken;
    if (!token) {
      throw createHttpError(
        "You are not logged in. Please log in to access this resource.",
        401
      );
    }
    const verifiedToken = jwtUtils.verifyToken(token, config_default.jwt_access_secret);
    if (!verifiedToken.success) {
      throw createHttpError(verifiedToken.error || "Invalid token", 401);
    }
    const { id, name, email, role } = verifiedToken.data;
    if (requiredRoles.length && !requiredRoles.includes(role)) {
      throw createHttpError(
        "Forbidden. You don't have permission to access this resource.",
        403
      );
    }
    const user = await prisma.users.findUnique({
      where: { id }
    });
    if (!user) {
      throw createHttpError("User not found!", 404);
    }
    if (user.status === "BANNED") {
      throw createHttpError(
        "Your account has been banned. Please contact support.",
        403
      );
    }
    req.user = { id, name, email, role };
    next();
  });
};

