import { Router as Router2 } from "express";

// src/module/auth/auth.controller.ts
import httpStatus3 from "http-status";

// src/module/auth/auth.service.ts
import bcrypt2 from "bcryptjs";
var loginUserDB = async (userData) => {
  const { email, password } = userData;
  const user = await prisma.users.findUniqueOrThrow({
    where: {
      email
    }
  });
  const isPasswordMatch = await bcrypt2.compare(password, user.password);
  if (!isPasswordMatch) {
    throw new Error("Invalid password");
  }
  const { password: _, ...userWithoutPassword } = user;
  const jwtPayload = {
    id: userWithoutPassword.id,
    name: userWithoutPassword.name,
    email: userWithoutPassword.email,
    role: userWithoutPassword.role
  };
  const accessToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_access_secret,
    config_default.jwt_access_expire_in
  );
  const refreshToken2 = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_refresh_secret,
    config_default.jwt_refresh_expire_in
  );
  return {
    accessToken,
    refreshToken: refreshToken2
  };
};
var refreshTokenDB = async (refreshToken2) => {
  const verifiedRefreshToken = jwtUtils.verifyToken(
    refreshToken2,
    config_default.jwt_refresh_secret
  );
  if (!verifiedRefreshToken.success) {
    throw new Error(verifiedRefreshToken.error || "Invalid refresh token");
  }
  const { id } = verifiedRefreshToken.data;
  const user = await prisma.users.findUniqueOrThrow({
    where: {
      id
    }
  });
  if (user.status === "BANNED") {
    throw new Error("User is banned");
  }
  const jwtPayload = {
    id: user.id,
    name: user.name,
    email: user.email,
    role: user.role
  };
  const accessToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_access_secret,
    config_default.jwt_access_expire_in
  );
  return {
    accessToken
  };
};
var authService = {
  loginUserDB,
  refreshTokenDB
};

// src/module/auth/auth.controller.ts
var loginUser = catchAsync(
  async (req, res, next) => {
    const payload = req.body;
    const { accessToken, refreshToken: refreshToken2 } = await authService.loginUserDB(payload);
    res.cookie("accessToken", accessToken, {
      httpOnly: true,
      secure: false,
      sameSite: "none",
      maxAge: 1e3 * 60 * 60 * 24
    });
    res.cookie("refreshToken", refreshToken2, {
      httpOnly: true,
      secure: false,
      sameSite: "none",
      maxAge: 1e3 * 60 * 60 * 24 * 7
    });
    sendResponse(res, {
      success: true,
      statusCode: httpStatus3.OK,
      message: "User logged in successfully",
      data: {
        accessToken,
        refreshToken: refreshToken2,
        payload: {
          email: payload.email
        }
      }
    });
    next();
  }
);
var refreshToken = catchAsync(
  async (req, res, next) => {
    const { refreshToken: refreshToken2 } = req.cookies;
    const { accessToken } = await authService.refreshTokenDB(refreshToken2);
    res.cookie("accessToken", accessToken, {
      httpOnly: true,
      secure: false,
      sameSite: "none",
      maxAge: 1e3 * 60 * 60 * 24
    });
    sendResponse(res, {
      success: true,
      statusCode: httpStatus3.OK,
      message: "Access token refreshed successfully",
      data: {
        accessToken,
        refreshToken: refreshToken2
      }
    });
    next();
  }
);
var authController = {
  loginUser,
  refreshToken
};

